+    const confirmation = await confirmHostedFields();
+    if (confirmation.error) {
+        return { state: 'payment-error', message: confirmation.error };
+    }
+
+    const payment = await readServerPayment();
+    if (!BOOKABLE.has(payment.status)) {
+        return { state: 'payment-pending', status: payment.status };
