+                    {confirming
+                        ? 'Authorizing your payment securely with Stripe.'
+                        : 'Confirming booking and checking availability.'}
+                </p>
+            )}
+        </form>
+    );
+}
+
+export default function CheckoutPaymentForm({
+    publishableKey,
+    clientSecret,
+    ...formProps
+}: CheckoutPaymentFormProps) {
